Input: Base datasets Dgsm8k and Dhotpotqa;
distractor sentence number k;
insertion positions P; distractor type
set T ; LLM generator
M = gpt-4o-mini
Output: Augmented noisy dataset Daug
Daug ←∅;
foreach base sample x ∈Dgsm8k ∪Dhotpotqa
do

Determine the topic tx and keyword set
Kx of x;
Initialize distractor set ∆x ←∅;
for i ←1 to k do

Select distractor type τi ∈T ;
Generate distractor di using M
conditioned on (tx, Kx, τi);
∆x ←∆x ∪{di};
Insert ∆x into x according to positions
P to obtain ˜x;
Daug ←Daug ∪{˜x};

// Phase 1: State Initialization &
Dataset Merging
S ←PreprocessAndMerge(Dbase, Dcot);

// Phase 2: Sample Annotation based
on Heuristics
foreach sample s ∈S do

// Phase 3: Feature Extraction &
Model Training
X ←ExtractFeatures(Dlabeled, d = 120);
y ←ExtractLabels(Dlabeled);
Xnorm ←StandardScaler(X);

Mgate ←InitializeMLP(hidden_dims =
[128, 64]);
M∗
gate ←
TrainWithGroupKFold(Mgate, Xnorm, y, K =
5);

// Initialize conversation history
with system and user prompts
H ←Psys ⊕FormatUserPrompt(q, c);

// Generate response from the
LLM
r ←MLLM(H);

// Execute tool and append
observation to the loop
o ←ExecuteTool(r.tool_call);
H ←H ⊕r ⊕o;
else

// Model attempts to submit
final answer without tool
calls
pcont ←Mgate(H, r) ;

// Continue the
interaction by
injecting the continue
prompt
H ←H ⊕r ⊕Pcont;
else

// Accept the submission
and halt
A ←ExtractFinalAnswer(r);
return A;

